window.__finlexDocLoaded(10136,{"id":10136,"articles":[{"id":1000594,"no":"Overview","heading":"Official Overview & Scope (IFRS Foundation)","text":"Superseded by IFRS 16 Leases.\n\nSIC-15 addresses how a lessee and a lessor account for incentives (such as rent-free periods or contributions by the lessor to the lessee's relocation costs) related to operating leases. Such incentives are accounted for as a reduction of lease income (lessor) or lease expense (lessee) over the lease term.","seq":0},{"id":1000595,"no":"History","heading":"Standard History & Amendments","text":"In April 2001 the International Accounting Standards Board adopted SIC-15 Operating Leases—Incentives, which had originally been issued by the Standing Interpretations Committee of the International Accounting Standards Committee in December 1998.\n\nSIC-15 was superseded by IFRS 16 Leases.","seq":1},{"id":1000596,"no":"Support","heading":"Related Projects & Implementation Support","text":"[Related IFRS Standards]\n• IAS 17 Leases\n• IFRS 16 Leases","seq":2},{"id":1000597,"no":"References","heading":"Official Text Link & Public Practical Guidance","text":"Official IFRS Foundation Page (English): https://www.ifrs.org/issued-standards/list-of-standards/sic-15-operating-leases-incentives/\nAccess Note: Free access to the unaccompanied text of IFRS Accounting Standards on ifrs.org requires a free registered IFRS.org account; Basis for Conclusions and Illustrative Examples require an IFRS Digital Subscription.\nPublic Companion Overview: KPMG Insights into IFRS — An Overview (Sept 2026): https://assets.kpmg.com/content/dam/kpmgsites/xx/pdf/ifrg/2026/isg-2026-insights-an-overview.pdf","seq":3}]});
